SELECT count(*) rows, count(DISTINCT sku_scanned) skus, count(DISTINCT bill_id) bills,
       min(bill_ts) lo, max(bill_ts) hi, sum(line_amount) amt
FROM store.pos_lines;

SELECT sku_scanned, count(*) n, min(unit_price) minp, max(unit_price) maxp,
       count(DISTINCT unit_price) nprices, min(bill_ts) lo, max(bill_ts) hi
FROM store.pos_lines GROUP BY 1 ORDER BY 1;

SELECT sku_scanned, unit_price, count(*) AS lines, min(bill_ts) AS first_ts, max(bill_ts) AS last_ts
FROM store.pos_lines
GROUP BY 1,2 ORDER BY 1,2;

SELECT w.date, w.sku, w.units, w.reason,
       (SELECT count(*) FROM store.goods_receipts g WHERE g.sku_booked = w.sku AND g.received_ts::date <= w.date) AS grns_to_date
FROM store.write_offs w WHERE w.sku='DAL-TOOR-1KG' ORDER BY w.date;

SELECT min(ts) AS min_ts, max(ts) AS max_ts, count(*) AS n FROM payments.pos_payments;
SELECT min(bill_ts) AS min_ts, max(bill_ts) AS max_ts, count(*) AS n FROM store.pos_lines;
SELECT min(initiated_ts), max(initiated_ts), count(*) FROM payments.psp_upi_report;

-- notes on payment attempts; UPI report rows with no till attempt; bill total vs payment mismatch
SELECT note, count(*) FROM payments.pos_payments GROUP BY 1 ORDER BY 2 DESC LIMIT 10;
SELECT count(*) AS upi_report_rows_without_till_attempt
FROM payments.psp_upi_report u
LEFT JOIN payments.pos_payments p ON p.rrn=u.rrn
WHERE p.rrn IS NULL;
WITH lt AS (SELECT bill_id, sum(line_amount) AS total FROM store.pos_lines GROUP BY bill_id),
     pa AS (SELECT bill_id, sum(amount_inr) FILTER (WHERE till_status='approved') AS paid FROM payments.pos_payments GROUP BY bill_id)
SELECT count(*) AS june_bills, count(*) FILTER (WHERE abs(lt.total-pa.paid)>0.01) AS amount_mismatch
FROM lt JOIN pa USING (bill_id) WHERE lt.bill_id IN (SELECT bill_id FROM store.pos_lines WHERE bill_ts >= '2026-06-01');

-- Q6: capital tied up in stock (latest book close) and Q7: till attempts in June
SELECT max(date) AS latest_book_date, count(*) AS rows_at_latest
FROM store.inventory_book WHERE date = (SELECT max(date) FROM store.inventory_book);

SELECT b.sku, b.book_on_hand_close, p.cost_inr, p.price_inr,
       b.book_on_hand_close * p.cost_inr AS capital_inr
FROM store.inventory_book b JOIN store.products p USING (sku)
WHERE b.date = (SELECT max(date) FROM store.inventory_book)
ORDER BY b.sku;

SELECT count(*) AS till_attempts_june FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

-- Q8: snacks category? Check for any category field anywhere; products have no category column.
SELECT count(*) FROM store.products;
-- check distinct skus in sales vs products
SELECT count(DISTINCT sku) FROM store.daily_sales;
SELECT count(DISTINCT sku_scanned) FROM store.pos_lines;
-- any snack-like product names?
SELECT sku, name FROM store.products WHERE name ILIKE '%snack%' OR name ILIKE '%chip%' OR name ILIKE '%biscuit%' OR name ILIKE '%namkeen%';
